using System;
using System.Collections.Immutable;
using System.Linq;
using Extensions.Pack;
using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("Basic")]
    [TestCategory("RJIT_CR_BC")]
    [TestCategory("RJIT_CR_BC_R")]
    [TestClass]
    public class RJIT_CR_BC_R_00002 : MsTestBase   
    {
        /*
         * Code Rule RJIT_CR_BC_R_00002 enforces that records should not have mutable properties. This rule aims to promote immutability within records, which can lead to safer and more predictable code, especially in multithreaded environments.
         */
        [TestMethod]
        public void Records_Should_Not_Have_Mutable_Properties()
        {
            var returnAwaitOnly = (from @record in Records
                where @record.Modifiers.Contains(Modifier.Static).IsFalse()
                from property in @record.Properties
                where property.IsReadOnly.IsFalse()
                select new
                {
                    ErrorClass = @record.FullQualifiedName, 
                    ErrorProperty = $"{property.Type} {property.Name}",
                    Error = $@"
Please do not use mutable property signatures.
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
FullName:  {@record.FullQualifiedName}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Property:  {property.Type} {property.Name}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Should be: {property.Type} {property.Name} {{get; init;}}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                }).ToImmutableList();

            Assert.IsTrue(returnAwaitOnly.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_BC_R_00002

Properties must be immutable. Findings: '{returnAwaitOnly.Count}':{Environment.NewLine}{returnAwaitOnly.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }
}
